-- Picnic expansion project: city data
-- 30 German cities where Picnic did not deliver (as of October 2026), with five indicators per city.
-- Sources are listed per city in the notes_source column. Years are mixed: population/area 2021 (Wikipedia),
-- income 2023 (Statistikportal VGR der Laender), household size May 2022 (Zensus 2022),
-- share aged 25-44 mostly 2023 (Wegweiser Kommune; 2021 for the five cities marked in notes_source).
-- Run with SQLite:  sqlite3 picnic_cities.db < picnic_cities.sql

DROP TABLE IF EXISTS cities;

CREATE TABLE cities (
    city                   TEXT PRIMARY KEY,
    state                  TEXT NOT NULL,
    population             INTEGER NOT NULL,   -- inhabitants, 31 Dec 2021
    area_km2               REAL NOT NULL,
    density_per_km2        REAL NOT NULL,      -- population / area_km2
    disposable_income_eur  INTEGER NOT NULL,   -- per inhabitant per year, 2023 (district value for 5 cities)
    avg_household_size     REAL NOT NULL,      -- persons per household, 15 May 2022 (district value for 5 cities)
    share_aged_25_44       REAL NOT NULL,      -- share of population aged 25-44
    picnic_serves_already  TEXT NOT NULL,      -- 'No' for all rows in this table
    notes_source           TEXT
);

